function Team({ team, club }) {
	const {
		teamName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = team;

	const { clubLogo } = club;
	return (
		<tr>
			<td className="team-name">
				<img src={clubLogo} alt="" /> {teamName}
			</td>
			<td>{points}</td>
			<td>{wins}</td>
			<td>{draws}</td>
			<td>{losses}</td>
			<td>{goalsFor}</td>
			<td>{goalsAgainst}</td>
			<td>{goalDifference}</td>
		</tr>
	);
}

export default Team;
